INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (13,13,'["Quels sont les principes fondamentaux d''un projet architectural et quelle est la différence entre un permis de construire et un permis d''aménager ?", "Comment lisez-vous un plan architectural et quels logiciels de conception (AutoCAD, Revit, SketchUp) maîtrisez-vous concrètement ?", "Qu''est-ce qu''un cahier des charges techniques dans un projet de construction et quel rôle joue l''assistant architecte dans sa rédaction ?", "Votre diplôme est en Marketing et Communication : qu''est-ce qui vous a conduit à postuler à un poste d''Assistant Architecte et qu''avez-vous fait concrètement pour combler cet écart de formation ?", "Décrivez précisément l''expérience professionnelle d''une année que vous avez acquise : en quoi était-elle liée, même partiellement, à l''architecture ou à l''aménagement ?", "Avez-vous suivi des formations complémentaires, des stages ou des projets personnels en lien avec l''architecture ou l''urbanisme depuis l''obtention de votre diplôme ?", "Pourquoi souhaitez-vous travailler dans le secteur public plutôt que dans une agence privée de communication ou d''événementiel, domaine de votre formation initiale ?", "Où vous voyez-vous professionnellement dans 3 ans, et comment ce poste d''Assistant Architecte s''inscrit-il dans ce projet ?", "Que savez-vous du rôle et des missions de l''Agence de Développement Régional Fès-Meknès, et citez un projet territorial qu''elle a porté ou qu''elle accompagne ?", "Selon vous, quels sont les principaux défis du développement urbain et architectural dans la région Fès-Meknès aujourd''hui ?"]','[]','{}','2026-08-27 13:28:05.469229') ON CONFLICT (id) DO NOTHING;